import json, sys, zlib

MASK = 0xffffffff
MAX_PAYLOAD = 4096


def solve(request):
    pages = [bytearray(bytes.fromhex(p)) for p in request["pages"]]
    npages = len(pages)
    checkpoint = request["checkpoint"]
    log = bytes.fromhex(request["log"])
    n = len(log)

    pos = 0
    prev_seq = 0
    last_seq = 0
    valid_bytes = 0

    # txid -> list of staged patch payloads (bytes), in log order
    active = {}

    while True:
        if pos + 13 > n:
            break
        plen = int.from_bytes(log[pos:pos + 4], "little")
        seq = int.from_bytes(log[pos + 4:pos + 8], "little")
        kind = log[pos + 8]
        txid = int.from_bytes(log[pos + 9:pos + 13], "little")

        # header validation
        if plen > MAX_PAYLOAD:
            break
        if seq == 0 or seq <= prev_seq:
            break
        if kind not in (1, 2, 3, 4):
            break
        if txid == 0:
            break

        end = pos + 13 + plen
        if end + 4 > n:
            break
        payload = log[pos + 13:end]
        crc = int.from_bytes(log[end:end + 4], "little")
        if (zlib.crc32(log[pos:end]) & MASK) != crc:
            break

        # payload shape validation
        page_index = byte_offset = byte_count = None
        if kind == 1 or kind == 4:
            if plen != 0:
                break
        elif kind == 2:
            if plen < 6:
                break
            page_index = int.from_bytes(payload[0:2], "little")
            byte_offset = int.from_bytes(payload[2:4], "little")
            byte_count = int.from_bytes(payload[4:6], "little")
            if byte_count <= 0:
                break
            if plen != 6 + byte_count:
                break
            if page_index >= npages:
                break
            if byte_offset + byte_count > len(pages[page_index]):
                break
        else:  # kind == 3
            if plen != 8:
                break

        # record is structurally valid
        pos = end + 4
        valid_bytes = pos
        last_seq = seq
        prev_seq = seq

        if kind == 1:
            active[txid] = []
        elif kind == 2:
            if txid in active:
                active[txid].append(payload)
        elif kind == 3:
            if txid in active:
                patches = active.pop(txid)
                count = int.from_bytes(payload[0:4], "little")
                digest = int.from_bytes(payload[4:8], "little")
                if count == len(patches) and seq > checkpoint:
                    acc = zlib.crc32(b"".join(patches)) & MASK
                    if acc == digest:
                        for pp in patches:
                            pi = int.from_bytes(pp[0:2], "little")
                            off = int.from_bytes(pp[2:4], "little")
                            cnt = int.from_bytes(pp[4:6], "little")
                            pages[pi][off:off + cnt] = pp[6:6 + cnt]
        else:  # kind == 4
            active.pop(txid, None)

    return {
        "pages": [bytes(p).hex() for p in pages],
        "valid_bytes": valid_bytes,
        "last_seq": last_seq,
    }


if __name__ == "__main__":
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.write(json.dumps(solve(json.loads(line))))
        out.write("\n")
    out.flush()
